import{_ as a,o as s,c as t,a6 as n}from"./chunks/framework.BJFjZBwW.js";const i="/dev/assets/OpenMQTTGateway-OTA-Update-Home-Assistant.B3Y3nvyI.png",m=JSON.parse('{"title":"System commands (ESP only)","description":"","frontmatter":{},"headers":[],"relativePath":"use/gateway.md","filePath":"use/gateway.md","lastUpdated":1737836062000}'),o={name:"use/gateway.md"};function r(l,e,p,c,d,u){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="system-commands-esp-only" tabindex="-1">System commands (ESP only) <a class="header-anchor" href="#system-commands-esp-only" aria-label="Permalink to &quot;System commands (ESP only)&quot;">​</a></h1><h2 id="restart-the-esp" tabindex="-1">Restart the ESP <a class="header-anchor" href="#restart-the-esp" aria-label="Permalink to &quot;Restart the ESP&quot;">​</a></h2><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;cmd&quot;:&quot;restart&quot;}&#39;</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>With Home Assistant, this command is directly available through MQTT auto discovery as a switch into the HASS OpenMQTTGateway device entities list.</p></div><h2 id="erase-the-esp-settings" tabindex="-1">Erase the ESP settings <a class="header-anchor" href="#erase-the-esp-settings" aria-label="Permalink to &quot;Erase the ESP settings&quot;">​</a></h2><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;cmd&quot;:&quot;erase&quot;}&#39;</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>With Home Assistant, this command is directly available through MQTT auto discovery as a switch into the HASS OpenMQTTGateway device entities list.</p></div><h2 id="retrieve-current-status-of-the-esp" tabindex="-1">Retrieve current status of the ESP <a class="header-anchor" href="#retrieve-current-status-of-the-esp" aria-label="Permalink to &quot;Retrieve current status of the ESP&quot;">​</a></h2><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;cmd&quot;:&quot;status&quot;}&#39;</code></p><h2 id="auto-discovery" tabindex="-1">Auto discovery <a class="header-anchor" href="#auto-discovery" aria-label="Permalink to &quot;Auto discovery&quot;">​</a></h2><p>You can deactivate the MQTT auto-discovery function, which enables you to create devices/entities with the Home Assistant convention automatically. This function is set to <code>true</code> at startup for 30 minutes unless you deactivate it.</p><h3 id="deactivate" tabindex="-1">Deactivate <a class="header-anchor" href="#deactivate" aria-label="Permalink to &quot;Deactivate&quot;">​</a></h3><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;disc&quot;:false}&#39;</code></p><h3 id="activate" tabindex="-1">Activate <a class="header-anchor" href="#activate" aria-label="Permalink to &quot;Activate&quot;">​</a></h3><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;disc&quot;:true}&#39;</code></p><p>If you want the settings to be kept upon gateway restart, you can save the state by adding <code>&quot;save&quot;:true</code> (ESP32 only). <code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;disc&quot;:false, &quot;save&quot;:true}&#39;</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Auto discovery is enabled by default on release binaries and platformio.</p></div><h2 id="activate-offline-mode" tabindex="-1">Activate Offline mode <a class="header-anchor" href="#activate-offline-mode" aria-label="Permalink to &quot;Activate Offline mode&quot;">​</a></h2><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;offline&quot;:true,&quot;save&quot;:true}&#39;</code></p><h2 id="change-the-wifi-credentials" tabindex="-1">Change the WiFi credentials <a class="header-anchor" href="#change-the-wifi-credentials" aria-label="Permalink to &quot;Change the WiFi credentials&quot;">​</a></h2><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;wifi_ssid&quot;:&quot;ssid&quot;, &quot;wifi_pass&quot;:&quot;password&quot;}&#39;</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the new connection fails the gateway will fallback to the previous connection.</p></div><h2 id="change-the-gateway-password" tabindex="-1">Change the gateway password <a class="header-anchor" href="#change-the-gateway-password" aria-label="Permalink to &quot;Change the gateway password&quot;">​</a></h2><p>The password must be 8 characters minimum.</p><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;gw_pass&quot;:&quot;12345678&quot;}&#39;</code></p><h2 id="change-the-mqtt-broker-credentials" tabindex="-1">Change the MQTT broker credentials <a class="header-anchor" href="#change-the-mqtt-broker-credentials" aria-label="Permalink to &quot;Change the MQTT broker credentials&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m</span></span>
<span class="line"><span>&#39;{</span></span>
<span class="line"><span>  &quot;mqtt_user&quot;: &quot;user_name&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_pass&quot;: &quot;password&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_server&quot;: &quot;host&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_port&quot;: &quot;port&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_validate&quot;: false,</span></span>
<span class="line"><span>  &quot;mqtt_secure&quot;: false</span></span>
<span class="line"><span>}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">INFO</p><p>By default this function is not available on the pre built binary of RFBridge, in order to have less code size and enable to have OTA update working properly. So as to enable it remove from the rf bridge env:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build_flags = &#39;-UMQTTsetMQTT&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the new connection fails the gateway will fallback to the previous connection.</p></div><h2 id="change-the-mqtt-main-topic-discovery-prefix-and-or-gateway-name" tabindex="-1">Change the MQTT main topic, discovery prefix, and or gateway name <a class="header-anchor" href="#change-the-mqtt-main-topic-discovery-prefix-and-or-gateway-name" aria-label="Permalink to &quot;Change the MQTT main topic, discovery prefix, and or gateway name&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m</span></span>
<span class="line"><span>&#39;{</span></span>
<span class="line"><span>  &quot;mqtt_topic&quot;: &quot;topic/&quot;,</span></span>
<span class="line"><span>  &quot;discovery_prefix&quot;: &quot;prefix&quot;,</span></span>
<span class="line"><span>  &quot;gateway_name&quot;: &quot;name&quot;</span></span>
<span class="line"><span>}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">INFO</p><p>This will change the subscribed and published mqtt_topic/gateway_name that the gateway uses. No parameters are mandatory, the current topic or gateway name will be used if not supplied.</p></div><h2 id="switching-brokers-and-using-signed-and-client-certificates" tabindex="-1">Switching brokers and using signed and client certificates <a class="header-anchor" href="#switching-brokers-and-using-signed-and-client-certificates" aria-label="Permalink to &quot;Switching brokers and using signed and client certificates&quot;">​</a></h2><p>In the <code>user_config.h</code> file it is possible to specify multiple MQTT brokers and client certificates. Additionally, support for multiple brokers and client certificates has been added. To use this, it is required that the server certificate, client certificate, and client key are provided as their own constant string value as demonstrated in the file.<br> To add more than one broker and switch between them it is necessary to provide all of the relevant certificates/keys and add their respective variable names in the <code>cnt_parameters_array</code> structure, as shown in <code>user_config.h</code>..</p><p>To switch between these connections with an MQTT command message, the format is as follows:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m</span></span>
<span class="line"><span>&#39;{</span></span>
<span class="line"><span>  &quot;mqtt_user&quot;: &quot;user&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_pass&quot;: &quot;password&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_server&quot;: &quot;host&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_port&quot;: &quot;port&quot;,</span></span>
<span class="line"><span>  &quot;mqtt_secure&quot;: true,</span></span>
<span class="line"><span>  &quot;mqtt_validate&quot;: true,</span></span>
<span class="line"><span>  &quot;cnt_index&quot;:1,</span></span>
<span class="line"><span>  &quot;save_cnt&quot;: true</span></span>
<span class="line"><span> }&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <code>cnt_index</code> value corresponds to the 0 to 2 index of the <code>cnt_parameters_array</code> in <code>user_config.h</code>. 0 being the default index, containing the onboarding parameters.</p></div><p>To read the connection parameters:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m</span></span>
<span class="line"><span>&#39;{</span></span>
<span class="line"><span>  &quot;cnt_index&quot;:1,</span></span>
<span class="line"><span>  &quot;read_cnt&quot;: true</span></span>
<span class="line"><span> }&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>To test a connection change without saving:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m</span></span>
<span class="line"><span>&#39;{</span></span>
<span class="line"><span> &quot;cnt_index&quot;:1,</span></span>
<span class="line"><span> &quot;test_cnt&quot;: true</span></span>
<span class="line"><span>}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the client can&#39;t connect to the MQTT broker corresponding to the current <code>cnt_index</code>, it will increment the index to the next valid connection set and restart with it.</p></div><h2 id="saving-loading-connection-parameters-certificates-at-runtime" tabindex="-1">Saving/Loading connection parameters/certificates at runtime <a class="header-anchor" href="#saving-loading-connection-parameters-certificates-at-runtime" aria-label="Permalink to &quot;Saving/Loading connection parameters/certificates at runtime&quot;">​</a></h2><p>This chapter details the process for managing certificates/connections parameters used for secure MQTT communication with OpenMQTTGateway</p><h3 id="storing-and-loading-certificates" tabindex="-1">Storing and Loading Certificates <a class="header-anchor" href="#storing-and-loading-certificates" aria-label="Permalink to &quot;Storing and Loading Certificates&quot;">​</a></h3><ul><li>Flash Memory Storage: Certificates can be saved to the flash memory using specific indices. Valid indices for storing certificates are 1 and 2, as 0 is reserved for the default certificate.</li><li>RAM Memory Loading: Certificates can be loaded from RAM, where valid indices range from 0 to 2. The device publishes a hash of the certificate to the broker to verify its identity. If the connection using the current certificate fails, the device will revert to the previous certificate.</li></ul><h3 id="use-case-changing-a-group-of-certificates" tabindex="-1">Use Case: Changing a Group of Certificates <a class="header-anchor" href="#use-case-changing-a-group-of-certificates" aria-label="Permalink to &quot;Use Case: Changing a Group of Certificates&quot;">​</a></h3><p>When updating certificates, follow these steps to ensure that the new certificates are correctly loaded and used:</p><ol><li>Push Certificates via MQTT: Send the new certificates one by one through MQTT, using indices 1 or 2. Replace newline characters (\\n) in the certificates with spaces.</li></ol><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cnt_index&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mqtt_server_cert&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-----BEGIN CERTIFICATE----- MIIDQTCC----END CERTIFICATE-----&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Accepted certificates are:</p><ul><li><code>mqtt_server_cert</code></li><li><code>mqtt_client_cert</code></li><li><code>mqtt_client_key</code></li><li><code>ota_server_cert</code></li></ul><ol start="2"><li>Verify Certificates in RAM: After pushing the certificates, verify that they have been correctly loaded into RAM.</li></ol><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cnt_index&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;read_cnt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ol start="3"><li>Test and Save Certificates: Once verification is complete, test the connection using the new certificates. If the connection is successful, send the command to save the certificates to flash.</li></ol><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cnt_index&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;save_cnt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ol start="4"><li><p>Broker Connection: The broker will attempt to use the newly received certificates for the connection.</p></li><li><p>Successful Connection Handling: If the connection is successful, the certificates are permanently stored in the flash memory at the specified index.</p></li><li><p>Handling Connection Failures: If the connection fails, the device will revert to the previously used certificate index, and the new certificates will not be saved.</p></li></ol><h1 id="firmware-update-from-mqtt-esp-only" tabindex="-1">Firmware update from MQTT (ESP only) <a class="header-anchor" href="#firmware-update-from-mqtt-esp-only" aria-label="Permalink to &quot;Firmware update from MQTT (ESP only)&quot;">​</a></h1><p>When the gateway used is from a standard ESP32 environment <a href="https://github.com/1technophile/OpenMQTTGateway/blob/development/environments.ini" target="_blank" rel="noreferrer">listed and defined here</a>, it can be updated through a simple MQTT command:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway_ESP32_BLE/commands/MQTTtoSYS/firmware_update&quot; -m &#39;{</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;latest&quot;</span></span>
<span class="line"><span>}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>This would download the latest version firmware binary from Github and install it. It can be used with version 1.5.0 and above.</p><p>Note that this update option is also autodiscovered through Home Assistant convention, you can update directly from the device page with 2 clicks.</p><p><img src="`+i+`" alt="Home Assistant OTA Update"></p><p>You can also indicate the target version to update:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway_ESP32_BLE/commands/MQTTtoSYS/firmware_update&quot; -m &#39;{</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;v1.2.0&quot;</span></span>
<span class="line"><span>}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>OpenMQTTGateway checks at start and every hour if an update is available.</p><p>Alternatively if you want to choose the update URL you can use the command below (ESP32 and ESP8266):</p><p>Without certificate, in this case the gateway will use the ota_server_cert certificate defined in default_ota_cert.h</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway_ESP32_BLE/commands/MQTTtoSYS/firmware_update&quot; -m &#39;{</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;test&quot;,</span></span>
<span class="line"><span>  &quot;password&quot;: &quot;OTAPASSWORD&quot;,</span></span>
<span class="line"><span>  &quot;url&quot;: &quot;https://github.com/1technophile/OpenMQTTGateway/releases/download/v0.9.12/esp32dev-ble-firmware.bin&quot;</span></span>
<span class="line"><span>}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>With certificate (replace the \\n in the certificate by spaces to publish it easily):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway_ESP32_BLE/commands/MQTTtoSYS/firmware_update&quot; -m &#39;{</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;test&quot;,</span></span>
<span class="line"><span>  &quot;password&quot;: &quot;OTAPASSWORD&quot;,</span></span>
<span class="line"><span>  &quot;url&quot;: &quot;https://github.com/1technophile/OpenMQTTGateway/releases/download/v0.9.12/esp32dev-ble-firmware.bin&quot;,</span></span>
<span class="line"><span>  &quot;ota_server_cert&quot;: &quot;-----BEGIN CERTIFICATE----- MIIDrzCCApegAwIBAgIQCDvgVpBCRrGhdWrJWZHHSjANBgkqhkiG9w0BAQUFADBh CAUw7C29C79Fv1C5qfPrmAESrciIxpg0X40KPMbp1ZWVbd4= -----END CERTIFICATE-----&quot;}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>A bash script is available <a href="ota_command_cert.zip">here also</a> to simplify the use of the <code>server_cert</code> parameter.</p><p>Alternatively the OTA certificate can also be saved with the cnt_index for future use:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t &quot;home/OpenMQTTGateway_ESP32_BLE/commands/MQTTtoSYS/config&quot; -m &#39;{</span></span>
<span class="line"><span>  &quot;cnt_index&quot;: 1,</span></span>
<span class="line"><span>  &quot;save_cnt&quot;:true,</span></span>
<span class="line"><span>  &quot;ota_server_cert&quot;: &quot;-----BEGIN CERTIFICATE----- MIIDrzCCApegAwIBAgIQCDvgVpBCRrGhdWrJWZHHSjANBgkqhkiG9w0BAQUFADBh CAUw7C29C79Fv1C5qfPrmAESrciIxpg0X40KPMbp1ZWVbd4= -----END CERTIFICATE-----&quot;</span></span>
<span class="line"><span>}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The other connection parameters corresponding to the index need to be valid for the save function to work. This command will switch to connection parameters of index 1.</p><p>To enable this functionality, <code>MQTT_HTTPS_FW_UPDATE</code> will need to be defined or the line that defines in in user_config.h will need to be uncommented.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If using an unsecure MQTT broker it is <strong>highly recommended</strong> to disable the password checking by setting the macro <code>MQTT_HTTPS_FW_UPDATE_USE_PASSWORD</code> to 0 (default is 1 (enabled)), otherwise a clear text password may be sent over the network.</p><p>The <code>server_cert</code> parameter is optional. If the update server has changed or certificate updated or not set in <code>user_config.h</code> then you can provide the certificate here.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The pre-built binaries for <strong>rfbridge</strong> and <strong>avatto-bakeey-ir</strong> have the above WiFi and MQTT broker credentials and the Firmware update via MQTT options disabled. This is due to the restricted available flash, so as to still be able to use OTA firmware updates for these boards.</p></div><h1 id="communication-layers" tabindex="-1">Communication layers <a class="header-anchor" href="#communication-layers" aria-label="Permalink to &quot;Communication layers&quot;">​</a></h1><h2 id="mqtt" tabindex="-1">MQTT <a class="header-anchor" href="#mqtt" aria-label="Permalink to &quot;MQTT&quot;">​</a></h2><p>OpenMQTTGateway uses per default MQTT on top of Ethernet or WiFi for communicating (default: true). The MQTT communication can be deactivated with the following command: <code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;mqtt&quot;:false}&#39;</code> Once activated the MQTT API is no longer accessible</p><h2 id="serial" tabindex="-1">Serial <a class="header-anchor" href="#serial" aria-label="Permalink to &quot;Serial&quot;">​</a></h2><p>Added to MQTT, OpenMQTTGateway cans use Serial to transmit or receive json data (default: false): <code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;serial&quot;:true}&#39;</code></p><p>The build need to have the following macro:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  &#39;-DZgatewaySERIAL=&quot;SERIAL&quot;&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>An example scenario is a slave offline ESP32 dedicated to RF decoding connected to another online ESP32 through Serial.</p><h1 id="indicators" tabindex="-1">Indicators <a class="header-anchor" href="#indicators" aria-label="Permalink to &quot;Indicators&quot;">​</a></h1><h2 id="change-the-led-indicator-brightness" tabindex="-1">Change the LED indicator brightness <a class="header-anchor" href="#change-the-led-indicator-brightness" aria-label="Permalink to &quot;Change the LED indicator brightness&quot;">​</a></h2><p>Minimum: 0, Maximum: 255, Default defined by DEFAULT_ADJ_BRIGHTNESS</p><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;brightness&quot;:200}&#39;</code></p><h2 id="understanding-led-indicators-in-openmqttgateway" tabindex="-1">Understanding LED Indicators in OpenMQTTGateway <a class="header-anchor" href="#understanding-led-indicators-in-openmqttgateway" aria-label="Permalink to &quot;Understanding LED Indicators in OpenMQTTGateway&quot;">​</a></h2><p>With boards having one or several RGB Led, OpenMQTTGateway uses them to provide visual feedback about its current state. This guide will help you interpret these LED signals to understand what&#39;s happening with your gateway.</p><h2 id="led-color-guide" tabindex="-1">LED Color Guide <a class="header-anchor" href="#led-color-guide" aria-label="Permalink to &quot;LED Color Guide&quot;">​</a></h2><p>OpenMQTTGateway uses a variety of colors to indicate different states:</p><p>Green (0x00FF00): Indicates normal operation or successful connections Blue (0x0000FF): Shows processing or offline status Orange (0xFFA500): Indicates waiting states or minor issues Yellow (0xFFFF00): Used during the onboarding process Red (0xFF0000): Signals an error state Magenta (0xFF00FF): Indicates local Over-The-Air (OTA) updates Purple (0x8000FF): Shows remote OTA updates are in progress</p><h2 id="understanding-gateway-states" tabindex="-1">Understanding Gateway States <a class="header-anchor" href="#understanding-gateway-states" aria-label="Permalink to &quot;Understanding Gateway States&quot;">​</a></h2><p>Here&#39;s what different LED behaviors mean:</p><h3 id="power-on" tabindex="-1">Power On <a class="header-anchor" href="#power-on" aria-label="Permalink to &quot;Power On&quot;">​</a></h3><p>Color: Green Behavior: Solid light Meaning: The gateway is powered and operational</p><h3 id="processing" tabindex="-1">Processing <a class="header-anchor" href="#processing" aria-label="Permalink to &quot;Processing&quot;">​</a></h3><p>Color: Blue Behavior: Blinking (3 times) Meaning: The gateway is processing data</p><h3 id="waiting-for-onboarding" tabindex="-1">Waiting for Onboarding <a class="header-anchor" href="#waiting-for-onboarding" aria-label="Permalink to &quot;Waiting for Onboarding&quot;">​</a></h3><p>Color: Orange Behavior: Solid light Meaning: The gateway is ready to be set up</p><h3 id="onboarding-in-progress" tabindex="-1">Onboarding in Progress <a class="header-anchor" href="#onboarding-in-progress" aria-label="Permalink to &quot;Onboarding in Progress&quot;">​</a></h3><p>Color: Yellow Behavior: Solid light Meaning: The gateway is being configured</p><h3 id="network-connected" tabindex="-1">Network Connected <a class="header-anchor" href="#network-connected" aria-label="Permalink to &quot;Network Connected&quot;">​</a></h3><p>Color: Green Behavior: Solid light Meaning: Successfully connected to the network</p><h3 id="network-disconnected" tabindex="-1">Network Disconnected <a class="header-anchor" href="#network-disconnected" aria-label="Permalink to &quot;Network Disconnected&quot;">​</a></h3><p>Color: Orange Behavior: Blinking Meaning: Lost connection to the network</p><h3 id="mqtt-broker-connected" tabindex="-1">MQTT Broker Connected <a class="header-anchor" href="#mqtt-broker-connected" aria-label="Permalink to &quot;MQTT Broker Connected&quot;">​</a></h3><p>Color: Green Behavior: Solid light Meaning: Successfully connected to the MQTT broker</p><h3 id="mqtt-broker-disconnected" tabindex="-1">MQTT Broker Disconnected <a class="header-anchor" href="#mqtt-broker-disconnected" aria-label="Permalink to &quot;MQTT Broker Disconnected&quot;">​</a></h3><p>Color: Orange Behavior: Blinking Meaning: Lost connection to the MQTT broker</p><h3 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h3><p>Color: Blue Behavior: Blinking Meaning: The gateway is offline</p><h3 id="local-ota-update" tabindex="-1">Local OTA Update <a class="header-anchor" href="#local-ota-update" aria-label="Permalink to &quot;Local OTA Update&quot;">​</a></h3><p>Color: Magenta Behavior: Blinking Meaning: A local Over-The-Air update is in progress</p><h3 id="remote-ota-update" tabindex="-1">Remote OTA Update <a class="header-anchor" href="#remote-ota-update" aria-label="Permalink to &quot;Remote OTA Update&quot;">​</a></h3><p>Color: Purple Behavior: Blinking Meaning: A remote Over-The-Air update is in progress</p><h3 id="error" tabindex="-1">Error <a class="header-anchor" href="#error" aria-label="Permalink to &quot;Error&quot;">​</a></h3><p>Color: Red Behavior: Blinking (3 times) Meaning: An error has occurred</p><h3 id="actuator-on-off" tabindex="-1">Actuator On/Off <a class="header-anchor" href="#actuator-on-off" aria-label="Permalink to &quot;Actuator On/Off&quot;">​</a></h3><p>Color: Green Behavior: Depends on actuator state Meaning: Indicates the state of a connected actuator</p>`,123)])])}const b=a(o,[["render",r]]);export{m as __pageData,b as default};
